def simulate_overlap(rows, cols, tile_size, shift_x, shift_y):
    board = [[0] * cols for _ in range(rows)]

    # Tile 1 placement (assumed at (0, 0))
    for i in range(tile_size):
        for j in range(tile_size):
            board[i][j] += 1

    # Tile 2 placement
    for i in range(tile_size):
        for j in range(tile_size):
            r, c = i + shift_x, j + shift_y
            if 0 <= r < rows and 0 <= c < cols:
                board[r][c] += 1

    # Count the frequency of each non-zero number
    counts = {}
    for r in range(rows):
        for c in range(cols):
            val = board[r][c]
            if val > 0:
                counts[val] = counts.get(val, 0) + 1

    return counts

# Test case: 2 tiles, S=52. We need a board large enough to capture the overlap interaction.
S = 52
# To capture the effect of T1 at (0,0) and T2 at (1,1), we need a board of at least 53x53.
R = S + 1
C = S + 1
shift_x = 1
shift_y = 1

distribution = simulate_overlap(R, C, S, shift_x, shift_y)
print(f"Distribution for 2 tiles, 1x1 shift (on {R}x{C} grid): {distribution}")

